using namespace std;
#define int long long
const int N=1e6+20;

inline int read(){
	int f=1,k=0;
	char c=getchar();
	while(c<'0'||c>'9'){
		if(c=='-') f=-1;
		c=getchar();
	}
	while(c>='0'&&c<='9'){
		k=(k<<1)+(k<<3)+(c^48);
		c=getchar();
	}
	return f*k;
}

int n,m;
struct mouse_king{
	int u,v,w;
	int id;
}edge1[N];
inline bool cmp(mouse_king a,mouse_king b){
	return a.w<b.w;
}
int f[N];
inline int find(int x){
	if(f[x]==x) return f[x];
	else return f[x]=find(f[x]);
}
inline void hb(int x,int y){
	x=find(x),y=find(y);
	if(x!=y) f[y]=x;
}
bool used[N];
int ans[N];
struct small_mouse{
	int minn,tag;
}t[N<<2];
struct big_mouse{
	int v,w,next;
}edge[N<<2];
int head[N];
int cnt;
inline void push_down(int p){
	if(t[p].tag!=1e18){
		t[p<<1].minn=min(t[p<<1].minn,t[p].tag);
		t[p<<1].tag=min(t[p<<1].tag,t[p].tag);
		t[p<<1|1].minn=min(t[p<<1|1].minn,t[p].tag);
		t[p<<1|1].tag=min(t[p<<1|1].tag,t[p].tag);
		t[p].tag=1e18;
	}
}
inline void push_up(int p){
	t[p].minn=min(t[p<<1].minn,t[p<<1|1].minn);
}
inline void build(int p,int l,int r){
	t[p].minn=t[p].tag=1e18;
	if(l==r) return;
	int mid=l+r>>1;
	build(p<<1,l,mid);
	build(p<<1|1,mid+1,r);
}
inline void update(int p,int l,int r,int dl,int dr,int k){
	if(dl<=l&&r<=dr){
		t[p].minn=min(t[p].minn,k);
		t[p].tag=min(t[p].tag,k);
		return;
	}
	int mid=l+r>>1;
	push_down(p);
	if(dl<=mid) update(p<<1,l,mid,dl,dr,k);
	if(dr>mid) update(p<<1|1,mid+1,r,dl,dr,k);
	push_up(p);
}
inline int ask(int p,int l,int r,int x){
	if(l==r) return t[p].minn;
	int mid=l+r>>1;
	push_down(p);
	if(x<=mid) return ask(p<<1,l,mid,x);
	else return ask(p<<1|1,mid+1,r,x);
}
inline void add(int u,int v,int w){
	edge[++cnt].v=v;
	edge[cnt].next=head[u];
	edge[cnt].w=w;
	head[u]=cnt;
	return;
}
int fa[N],dep[N],son[N],top[N],siz[N],id[N],idx;
inline void dfs1(int p,int fath){
	fa[p]=fath;
	dep[p]=dep[fath]+1;
	siz[p]=1;
	for(int i=head[p];i;i=edge[i].next){
		int v=edge[i].v;
		if(v!=fath){
			dfs1(v,p);
			siz[p]+=siz[v];
			if(siz[v]>siz[son[p]])
				son[p]=v;
		}
	}
	return;
}
inline void dfs2(int p,int ta){
	id[p]=++idx;
	top[p]=ta;
	if(!son[p]) return;
	dfs2(son[p],ta);
	for(int i=head[p];i;i=edge[i].next){
		int v=edge[i].v;
		if(v!=fa[p]&&v!=son[p])
			dfs2(v,v);
	}
	return;
}
inline void change(int x,int y,int k){
	while(top[x]!=top[y]){
		if(dep[top[x]]<dep[top[y]]) swap(x,y);
		update(1,1,n,id[top[x]],id[x],k);
		x=fa[top[x]];
	}
	if(dep[x]<dep[y]) swap(x,y);
	if(x!=y) update(1,1,n,id[y]+1,id[x],k);
	return;
}
signed main(){
	n=read(),m=read();
	for(int i=1;i<=m;i++){
		edge1[i].u=read();
		edge1[i].v=read();
		edge1[i].w=read();
		edge1[i].id=i;
	}
	sort(edge1+1,edge1+m+1,cmp);
	for(int i=1;i<=n;i++){
		f[i]=i;
	}
	int sum=0,tot=0;
	for(int i=1;i<=m;i++){
		int u=edge1[i].u,v=edge1[i].v;
		int w=edge1[i].w;
		if(find(u)!=find(v)){
			tot++;
			sum+=w;
			hb(u,v);
			used[i]=1;
			add(u,v,w),add(v,u,w);
		}
	}
	if(tot!=n-1){
		for(int i=1;i<=m;i++) cout<<-1<<endl;
		return 0;
	}
	dfs1(1,0);
	dfs2(1,1);
	build(1,1,n);
	for(int i=1;i<=m;i++){
		if(used[i]) continue;
		int u=edge1[i].u,v=edge1[i].v,w=edge1[i].w;
		change(u,v,w);
	}
	for(int i=1;i<=m;i++){
		int u=edge1[i].u,v=edge1[i].v;
		if(!used[i]){
			ans[edge1[i].id]=sum;
			continue;
		}
		if(dep[u]<dep[v]) swap(u,v);
