		for (I & j : g[i][0]) { j = C(j, f[i][0].back()); }
	}
}

I ask(int u, int d)
{
	int p = u; if (p == 1) { p = 2; }
	while (mx[_fa[p]] <= d and _fa[p]) { p = _fa[p]; }
	return C(G(p, 0, d - dis(u, U[p])), G(p, 1, d - dis(u, V[p])));
}
