using namespace std;
typedef long long ll;
const int N = 100005;
struct Edge {
	int v, next;
} edge[2 * N];
int head[N];
int cnt;
void add_edge(int u, int v) {
	cnt++;
	edge[cnt].v = v;
	edge[cnt].next = head[u];
	head[u] = cnt;
}
ll a[N];
int b[N], c[N];
__int128 ddl[N];
__int128 high(int u, __int128 x) {
	if (c[u] >= 0) {
		return b[u] * x + x * (x + 1) / 2 * c[u];
	} else {
		if (x <= ddl[u]) {
			return b[u] * x + x * (x + 1) / 2 * c[u];
		} else {
			return b[u] * ddl[u] + ddl[u] * (ddl[u] + 1) / 2 * c[u] + (x - ddl[u]);
		}
	}
}
bool enough(int u, __int128 x, __int128 target) {
	if (c[u] >= 0) {
		return b[u] * x + x * (x + 1) / 2 * c[u] <= target;
	} else {
		if (x <= ddl[u]) {
			return b[u] * x + x * (x + 1) / 2 * c[u] <= target;
		} else {
			return b[u] * ddl[u] + ddl[u] * (ddl[u] + 1) / 2 * c[u] + (x - ddl[u]) <= target;
		}
	}
}
int max(int a, int b) {
	return a > b ? a : b;
}
int min(int a, int b) {
	return a < b ? a : b;
}
int n, r[N], s[N];
void dfs(int u, int fa) {
	for (int v, i = head[u]; i != 0; i = edge[i].next) {
		v = edge[i].v;
		if (v != fa) {
			dfs(v, u);
			r[u] = min(r[u], r[v]);
		}
	}
}
bool check(int x) {
	if (x < n) {
		return false;
	}
	for (int u = 1; u <= n; u++) {
		__int128 target = high(u, x) - a[u];
		if (target < 0) {
			return false;
		}
		r[u] = 1;
		for (int i = 29; i >= 0; i--) {
			if (r[u] + (1 << i) <= x && enough(u, r[u] + (1 << i) - 1, target)) {
				r[u] += 1 << i;
			}
		}
	}
	dfs(1, 0);
	for (int i = 1; i <= n; i++) {
		s[i] = 0;
	}
	for (int u = 1; u <= n; u++) {
		if (r[u] < 1) {
			return false;
		}
		s[min(r[u], n)]++;
	}
	int sum = 0;
	for (int i = 1; i <= n; i++) {
		sum += s[i];
		if (sum > i) {
			return false;
		}
	}
	return true;
}
int main() {
	scanf("%d", &n);
	for (int i = 1; i <= n; i++) {
		scanf("%lld %d %d", &a[i], &b[i], &c[i]);
		if (c[i] < 0) {
			ddl[i] = (b[i] - 1) / (-c[i]);
		}
	}
