	if(T<l) return r-l+1;
	if(T>r) return (r-l+1)*b[x]+(r-l+1)*(l+r)/2*c[x];
	return (T-l+1)*b[x]+(T-l+1)*(l+T)/2*c[x]+r-T;
}
inline bool check(int r)
{
	for(int i=1;i<=n;i++) 
