int fd(int x){
	if(x==ff[x])return x;
	return ff[x]=fd(ff[x]);
}
void dfs(int x){
	for(int i=1;i<=18;i++){
		f1[x][i]=f1[f1[x][i-1]][i-1];
		f2[x][i]=min(f2[x][i-1],f2[f1[x][i-1]][i-1]);
	}
