	for(auto c:jl[x]){
		fs[x].push_back({l[c],h[fd(dy[c])],-1});
		sz[fd(dy[c])]--;
		sm[x]++;
	}
	for(auto c:g[x]){
		fs[x].push_back({h[x]+1,h[c],-sz[c]});
		sz[x]+=sz[c];
		ff[c]=x;
		sm[x]++;
	}
}
int gets(int l,int r){
	if(l>nw)return 0;
	if(l>r)return 0;
	return dp[min(r,nw)]-dp[l-1];
}
void solve(int x,int res){
	if(mk[x])for(auto c:fs[x])res+=gets(c.l,c.r)*c.op,res%=mods;
