	} n = a.size() - 1;
	for (int i = 1; i <= n; t[a[i]] = i, i++)
		if (t[a[i]])
			suf[t[a[i]]] = i; 
	for (int i = n; i; i--)
		if (suf[i])
			f[i] = max(f[i + 1], f[suf[i] - 1] + a[i]);
		else
			f[i] = f[i + 1];
	cout << ans + f[1] << '\n';
}

