using namespace std;

const int N = 5e5 + 5;
#define pq priority_queue<int, vector<int>, greater<int>>

vector<int> e[N];
int n, m;
bool cir[N], vis[N], can;

void findcir( int u, int fa ) {
    vis[u] = 1;
    for( auto v : e[u] ) {
        if( v == fa ) continue;
        if( vis[v] ) {
            cir[u] = cir[v] = 1;
            can = 1;
            return ;
        }
        findcir( v, u );
        if( cir[v] && can ) {
            if( cir[u] ) can = 0;
            cir[u] = 1;
            return ;
        }
    }
}

void dfs( int u, int lst ) {
    if( vis[u] ) return ;
    vis[u] = 1;
    printf( "%d ", u );
    pq q; int cnt = 0;
    for( auto v : e[u] ) 
        if( !vis[v] ){
            q.push( v );
            cnt += (cir[v] ^ 1);
        }
    while( !q.empty() ) {
        int v = q.top(); q.pop();
        if( vis[v] ) continue;
        if( can == 0 && !cnt && v > lst && !vis[lst] ) {
            can = 1;
            return;
        }
        cnt -= (cir[v] ^ 1);
        dfs( v, ( q.empty() || !cir[u] ) ? lst : q.top() );
    }
}

int main() {
    scanf( "%d%d", &n, &m );
    while( m-- ) {
        int u, v;
        scanf( "%d%d", &u, &v );
        e[u].push_back( v ), e[v].push_back( u );
    }
    findcir( 1, 0 );
    memset( vis, 0, sizeof vis );
    dfs( 1, 1e9 );
    return 0;
}
