	void ini(int x){
		if(x>n) return A[x]=B[x]=R[x]=++ct,void();
		ini(ls[x]),ini(rs[x]);
		A[x]=A[A[x]+n],B[x]=B[B[x]+n];
		R[x]=ct;
	}
	void dfs(int x){
		static int pt,f[500010];
		f[pt++]=x,s[x]=1,son[x]=0;
