void build(int l,int r,int k){
	ll[k] = l,rr[k] = r;
	dep[k] = dep[k>>1]+1;
	if(l == r){son[k].push_back(k);val[k].push_back(p[k]);return;}
	int mid = l+r>>1;
	build(l,mid,k<<1),build(mid+1,r,k<<1|1);
