	for(auto x:val[k<<1|1])val[k].push_back(x);
}
void work(int now){
	if(now>=tot){
		for(int i =0;i<=n;i++)dp[now][i]=inf;
		dp[now][max(c[now],b[now])] = 0;
		return;
	}
	work(now<<1),work(now<<1|1);

