            for(int k=i;k<=n;k++)
                mat[j][k]=mat[j][k]-mat[i][k]*t;
        }
    }
    poly res;
    if(f==1)res=poly(1,0);
    else res=poly(p-1,0);
    for(int i=1;i<=n;i++)res=res*mat[i][i];
    return res.x1;
}
